var scene=UnityEngine.SceneManagement.SceneManager.CreateScene("Isolated motor checks",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics2D));var physics=scene.GetPhysicsScene2D();
var host=new UnityEngine.GameObject("Isolated motor rig");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(host,scene);host.SetActive(false);
var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Character.prefab");var clone=UnityEngine.Object.Instantiate(prefab,host.transform);
foreach(var m in clone.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true))if(!(m is Character.Control.TargetMovement)&&!(m is Character.Control.ArmsSimulation))UnityEngine.Object.DestroyImmediate(m);
host.SetActive(true);var arms=clone.GetComponentInChildren<Character.Control.ArmsSimulation>();var input=clone.GetComponentInChildren<Character.Control.TargetMovement>();input.enabled=false;input.ResetTarget();
var body=clone.transform.Find("Cauldron").GetComponent<UnityEngine.Rigidbody2D>();body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;
foreach(var rb in clone.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.gravityScale=0;
void Tick(int n){for(int i=0;i<n;i++){arms.SendMessage("FixedUpdate");physics.Simulate(.02f);}}
try{
 var before=input.VirtualTarget;input.ApplyRelativeMotion(new UnityEngine.Vector2(15,10));var after=input.VirtualTarget;
 if(UnityEngine.Vector2.Distance(before,after)<.01f)throw new System.Exception("Relative delta ignored");input.ApplyRelativeMotion(UnityEngine.Vector2.zero);if(UnityEngine.Vector2.Distance(after,input.VirtualTarget)>.0001f)throw new System.Exception("Zero input drifts");
 var origin=(UnityEngine.Vector2)body.position;arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,1.6f));Tick(180);var final=(UnityEngine.Vector2)arms.HammerTip.position-origin;
 string log="Relative input moved target="+UnityEngine.Vector2.Distance(before,after)+"; zero delta stable; up direction final="+final+" angleError="+arms.AngleError+" extensionError="+arms.ExtensionError;
 if(UnityEngine.Mathf.Abs(arms.AngleError)>8)throw new System.Exception("Turn direction/convergence failed "+log);
 arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,1.1f));Tick(160);float shortReach=UnityEngine.Vector2.Distance(body.position,arms.HammerTip.position);
 arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,1.85f));Tick(160);float longReach=UnityEngine.Vector2.Distance(body.position,arms.HammerTip.position);
 log+="; radial short="+shortReach+" long="+longReach;
 if(longReach-shortReach<.35f)throw new System.Exception("Extension motor failed "+log);

 arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,-.95f));Tick(220);
 var shape=clone.transform.Find("Hammer/Shape").GetComponent<UnityEngine.PolygonCollider2D>();
 var floor=new UnityEngine.GameObject("Isolated support floor");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(floor,scene);var fc=floor.AddComponent<UnityEngine.BoxCollider2D>();fc.size=new UnityEngine.Vector2(12,.2f);floor.transform.position=new UnityEngine.Vector3(body.position.x,shape.bounds.min.y-.11f,0);
 log+="; pre-support tip="+(arms.HammerTip.position-(UnityEngine.Vector3)origin)+" slide="+clone.GetComponentInChildren<UnityEngine.SliderJoint2D>().jointTranslation;
 body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeRotation;float startY=body.position.y;
 arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,-2.8f));UnityEngine.Physics2D.SyncTransforms();Tick(100);float rise=body.position.y-startY;
 log+="; blocked paddle lifts body="+rise;
 if(rise<.08f)throw new System.Exception("Support reaction failed "+log);
 arms.enabled=false;var hinge=clone.GetComponentInChildren<UnityEngine.HingeJoint2D>();var slide=clone.GetComponentInChildren<UnityEngine.SliderJoint2D>();if(hinge.useMotor||slide.useMotor)throw new System.Exception("Disabled motors remain active");
 System.IO.File.WriteAllText("scripts/paddle-motor-control-20261111/check.txt",log+"; disabled motors off");UnityEngine.Debug.Log(log);
}finally{UnityEngine.Object.DestroyImmediate(host);UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);}
